def commands(binary_str):
    handshake_actions = []
    should_reverse = False

    # The problem specifies that the input binary_str will be a 5-digit string.
    # We process the bits from right to left, adding actions in that order.

    # Bit 0 (rightmost, index 4): wink
    if binary_str[4] == '1':
        handshake_actions.append("wink")

    # Bit 1 (second from right, index 3): double blink
    if binary_str[3] == '1':
        handshake_actions.append("double blink")

    # Bit 2 (third from right, index 2): close your eyes
    if binary_str[2] == '1':
        handshake_actions.append("close your eyes")

    # Bit 3 (fourth from right, index 1): jump
    if binary_str[1] == '1':
        handshake_actions.append("jump")

    # Bit 4 (leftmost, index 0): Reverse the order of operations
    if binary_str[0] == '1':
        should_reverse = True

    if should_reverse:
        handshake_actions.reverse()

    return handshake_actions
